mapper.select:
		SET LOCK_TIMEOUT 10000;
        SELECT *
        FROM   CHEKSTD WITH(NOLOCK) INNER JOIN
        FACILITY WITH(NOLOCK) ON CHEKSTD.FAC_CODE = FACILITY.FAC_CODE
        WHERE CHS_CODE = #{chs_code}

SET LOCK_TIMEOUT 10000;
WITH CROSSCHEKSTD AS ( SELECT CHEKSTD.CHS_CODE AS CHS_STD_CODE, CHEKSTD.CHS_CODE as CHS_STD_NO, CHEKSTD.CHS_SORT as CHS_SORT, CHEKSTD.CHS_HANG, CHEKSTD.CHS_IMG, CHEKSTD.CHS_KIJUN, CHEKSTD.CHS_MIN, CHEKSTD.CHS_MAX, CHEKSTD.CHS_DANW, CHEKSTD.CHS_GUBN, CHEKSTD.CHS_CHKMETHOD, CHEKSTD.CHS_STEPMETHOD, CHEKSTD.CHS_GUBN_DETAIL, CHEKSTD.FAC_CODE AS CSTD_FAC_CODE, FAC_NO, FAC_NAME FROM CHEKSTD WITH(NOLOCK) INNER JOIN FACILITY WITH (NOLOCK) ON CHEKSTD.FAC_CODE = FACILITY.FAC_CODE WHERE 1=1 AND CHEKSTD.FAC_CODE = #{fac_code} AND CHEKSTD.CHS_GUBN = #{chs_gubn} )--주야간 강제 생성 , JONJAE AS ( SELECT CROSSCHEKSTD.*, DAILY_CHECK.* FROM CROSSCHEKSTD INNER JOIN FACILITY WITH (NOLOCK) ON CROSSCHEKSTD.CSTD_FAC_CODE = FACILITY.FAC_CODE LEFT OUTER JOIN DAILY_CHECK WITH (NOLOCK) ON DAILY_CHECK.FAC_CODE = CROSSCHEKSTD.CSTD_FAC_CODE AND DAILY_CHECK.CHS_CODE = CROSSCHEKSTD.CHS_STD_CODE AND DAILY_CHECK.CHE_GUBN = CROSSCHEKSTD.CHS_GUBN AND DAILY_CHECK.CHE_GUBN_DETAIL = CROSSCHEKSTD.CHS_GUBN_DETAIL WHERE 1 = 1 AND DAILY_CHECK.CHE_DATE BETWEEN substring(#{sdate}, 1, 10) + ' 00:09:00' AND dateadd(day,1,substring(#{sdate}, 1, 10) + ' 00:09:00') )--해당 일자에 존재리스트
SELECT CROSSCHEKSTD.* FROM CROSSCHEKSTD LEFT OUTER JOIN JONJAE ON CROSSCHEKSTD.CHS_STD_CODE = JONJAE.CHS_CODE AND CROSSCHEKSTD.CHS_GUBN = JONJAE.CHS_GUBN AND CROSSCHEKSTD.CHS_GUBN_DETAIL = JONJAE.CHE_GUBN_DETAIL where 1=1
AND CROSSCHEKSTD.CHS_SORT = #{chs_sort}
AND JONJAE.CHS_CODE IS NULL AND crossCHEKSTD.CHS_GUBN_DETAIL = #{chs_gubn_detail}
